{"chunk_id":"f7cd13","wall_time_seconds":0.000013062,"exit_code":0,"original_token_count":3125,"output":"import { createBoard, type Board } from "./board.ts";
import { MAX_ELAPSED_MS, MAX_MOVES, MISMATCH_DURATION_MS } from "./timing.ts";

export type Selection =
  | Readonly<{ kind: "closed" }>
  | Readonly<{ kind: "one"; index: number }>
  | Readonly<{ kind: "mismatch"; first: number; second: number; remainingMs: number }>;

export type GameState = Readonly<{
  board: Board;
  matched: readonly number[];
  selection: Selection;
  moves: number;
  elapsedMs: number;
  started: boolean;
}>;

const CLOSED: Selection = Object.freeze({ kind: "closed" });

export function createGame(boardCode: string): GameState | null {
  const board = createBoard(boardCode);
  return board ? Object.freeze({ board, matched: Object.freeze([]), selection: CLOSED,
    moves: 0, elapsedMs: 0, started: false }) : null;
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.board.deck.length;
}

export function matchedPairs(state: GameState): number {
  return state.matched.length / 2;
}

function withMove(state: GameState): number {
  return Math.min(state.moves + 1, MAX_MOVES);
}

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isSafeInteger(index) || index < 0 || index >= state.board.deck.length || isWon(state)) return state;
  if (state.matched.includes(index) || state.selection.kind === "mismatch") return state;
  const started = true;
  switch (state.selection.kind) {
    case "closed":
      return Object.freeze({ ...state, started, selection: Object.freeze({ kind: "one", index }) });
    case "one": {
      if (index === state.selection.index) return state;
      const first = state.selection.index;
      const moves = withMove(state);
      if (state.board.deck[first] === state.board.deck[index]) {
        return Object.freeze({ ...state, started, moves,
          matched: Object.freeze([...state.matched, first, index]), selection: CLOSED });
      }
      return Object.freeze({ ...state, started, moves,
        selection: Object.freeze({ kind: "mismatch", first, second: index,
          remainingMs: MISMATCH_DURATION_MS }) });
    }
    case "mismatch":
      return state;
  }
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isSafeInteger(milliseconds) || milliseconds < 0 || isWon(state)) return state;
  const elapsedMs = state.started
    ? milliseconds >= MAX_ELAPSED_MS - state.elapsedMs
      ? MAX_ELAPSED_MS
      : state.elapsedMs + milliseconds
    : state.elapsedMs;
  if (state.selection.kind === "mismatch") {
    if (milliseconds >= state.selection.remainingMs) {
      return Object.freeze({ ...state, elapsedMs, selection: CLOSED });
    }
    return Object.freeze({ ...state, elapsedMs,
      selection: Object.freeze({ ...state.selection, remainingMs: state.selection.remainingMs - milliseconds }) });
  }
  return elapsedMs === state.elapsedMs ? state : Object.freeze({ ...state, elapsedMs });
}
export const MISMATCH_DURATION_MS = 800;
export const MAX_ELAPSED_MS = 359_999_999;
export const MAX_MOVES = 999_999;

export function formatTime(milliseconds: number): string {
  const seconds = Math.floor(milliseconds / 1_000);
  const minutes = Math.floor(seconds / 60);
  return `${minutes}:${String(seconds % 60).padStart(2, "0")}`;
}
export const BOARD_SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
export const MAX_BOARD_SEED = 2_147_483_646;
const PARK_MILLER_MODULUS = 2_147_483_647;
const PARK_MILLER_MULTIPLIER = 16_807;

export type BoardSize = (typeof BOARD_SIZES)[number];
export type Board = Readonly<{
  code: string;
  size: BoardSize;
  deck: readonly number[];
}>;

export function isBoardSize(value: unknown): value is BoardSize {
  return BOARD_SIZES.some((size) => size === value);
}

export function parseBoardCode(value: unknown): { size: BoardSize; seed: number } | null {
  if (typeof value !== "string") return null;
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(value);
  if (!match) return null;
  const size = Number(match[1]);
  const seed = Number(match[2]);
  return isBoardSize(size) && Number.isSafeInteger(seed) && seed <= MAX_BOARD_SEED
    ? { size, seed }
    : null;
}

export function parkMillerNext(state: number): number {
  return (state * PARK_MILLER_MULTIPLIER) % PARK_MILLER_MODULUS;
}

function drawBelow(state: number, bound: number): [number, number] {
  const range = PARK_MILLER_MODULUS - 1;
  const limit = Math.floor(range / bound) * bound;
  let next = state;
  let value = range;
  while (value >= limit) {
    next = parkMillerNext(next);
    value = next - 1;
  }
  return [value % bound, next];
}

export function createBoard(code: string): Board | null {
  const parsed = parseBoardCode(code);
  if (!parsed) return null;
  const count = parsed.size * parsed.size;
  const deck = Array.from({ length: count }, (_, index) => Math.floor(index / 2));
