/work/src/game/Game.css.content:
.neon-app {
  width: 100%;
  max-width: 1120px;
  min-width: 0;
  margin: 0 auto;
  padding: 24px 16px 32px;
}

.neon-header {
  margin-bottom: 24px;
}

.neon-eyebrow {
  margin-bottom: 4px;
  color: #63E7FF;
  font-size: 14px;
  line-height: 20px;
}

.neon-header h1 {
  font-size: 24px;
  font-weight: 700;
  line-height: 32px;
}

.neon-intro,
.neon-section-heading p,
.neon-footer {
  color: #B8BDD2;
  font-size: 14px;
  line-height: 20px;
}

.neon-intro {
  margin-top: 4px;
}

.neon-screen-reader-status {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  clip-path: inset(50%);
}

.neon-win-banner {
  margin-bottom: 16px;
  padding: 12px 16px;
  border: 1px solid #8BEA7D;
  border-radius: 12px;
  background: #141827;
}

.neon-win-banner h2,
.neon-section-heading h2 {
  font-size: 18px;
  font-weight: 650;
  line-height: 24px;
}

.neon-win-banner p {
  margin-top: 4px;
  color: #B8BDD2;
  font-size: 14px;
  line-height: 20px;
}

.neon-win-banner--pulse {
  animation: neon-win-pulse 600ms ease-out both;
}

@keyframes neon-win-pulse {
  0% { transform: scale(0.99); }
  45% { transform: scale(1.02); }
  100% { transform: scale(1); }
}

.neon-game-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(232px, 272px);
  align-items: start;
  gap: 24px;
}

.neon-board-section,
.neon-tools {
  min-width: 0;
}

.neon-section-heading {
  display: grid;
  gap: 4px;
  margin-bottom: 8px;
}

.neon-tools {
  display: grid;
  gap: 16px;
}

.neon-footer {
  margin-top: 24px;
}

@media (max-width: 760px) {
  .neon-game-layout {
    grid-template-columns: minmax(0, 1fr);
    gap: 16px;
  }

  .neon-tools {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    align-items: start;
    gap: 12px;
  }
}

@media (max-width: 520px) {
  .neon-tools {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (prefers-reduced-motion: reduce) {
  .neon-win-banner--pulse {
    animation: none;
  }
}

