  await expect(cards(page).nth(0)).toHaveAttribute("aria-label", /revealed$/);
  await page.clock.runFor(1);
  await cards(page).nth(2).click();
  await expect(cards(page).nth(2)).toHaveAttribute("aria-label", /revealed$/);
