import { mkdirSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { expect, test } from "@playwright/test";
import { cards, CODE_4, MATCHES } from "./helpers.ts";

async function moveTo(page: import("@playwright/test").Page, from: number, to: number): Promise<number> {
  const side = 4;
  let current = from;
  let column = current % side;
  const targetColumn = to % side;
  while (column < targetColumn) { await page.keyboard.press("ArrowRight"); current += 1; column += 1; }
  while (column > targetColumn) { await page.keyboard.press("ArrowLeft"); current -= 1; column -= 1; }
  while (current < to) { await page.keyboard.press("ArrowDown"); current += side; }
  while (current > to) { await page.keyboard.press("ArrowUp"); current -= side; }
  await expect(cards(page).nth(to)).toBeFocused();
  return current;
}

test("complete 4x4 keyboard and accessibility tree journey", async ({ page }) => {
  await page.goto("http://127.0.0.1:4173/");
  await page.keyboard.press("Tab");
  await expect(page.getByRole("combobox", { name: "Grid size" })).toBeFocused();
  await page.keyboard.press("Tab");
  await expect(page.getByRole("button", { name: "New Game" })).toBeFocused();
  await page.keyboard.press("Tab");
  await expect(page.getByRole("button", { name: "Restart" })).toBeFocused();
  await page.keyboard.press("Tab");
  await expect(cards(page).nth(0)).toBeFocused();
  await expect(cards(page).nth(0)).toHaveAttribute("aria-label", "Row 1, column 1, closed");
  await page.keyboard.press("Enter");
  await expect(cards(page).nth(0)).toHaveAttribute("aria-label", /revealed$/);
  expect((await cards(page).nth(0).getAttribute("aria-label"))?.includes("closed")).toBe(false);

  let current = 0;
  for (const [first, second] of MATCHES) {
    if (current !== first) current = await moveTo(page, current, first);
    if (first !== 0) await page.keyboard.press("Enter");
    expect((await cards(page).nth(first).getAttribute("aria-label"))?.endsWith("revealed")).toBe(true);
    current = await moveTo(page, current, second);
    await page.keyboard.press("Space");
    await expect(cards(page).nth(first)).toHaveAttribute("aria-disabled", "true");
  }

  await expect(page.getByRole("heading", { name: "All pairs found!" })).toBeVisible();
  await expect(page.getByText("Pairs: 8/8", { exact: true })).toBeVisible();
  await expect(page.getByText("Moves: 8", { exact: true })).toBeVisible();
  await expect(page.getByRole("status")).toContainText("Pair found. All pairs found in 8 moves and ");
  mkdirSync(resolve("artifacts"), { recursive: true });
  writeFileSync(resolve("artifacts/accessibility-tree.yaml"), `${await page.locator("body").ariaSnapshot()}\n`);
  await page.keyboard.press("Tab");
  await expect(page.getByText("Reproduce a game", { exact: true })).toBeFocused();
  await page.keyboard.press("Shift+Tab");
  await page.keyboard.press("Shift+Tab");
  await expect(page.getByRole("button", { name: "New Game" })).toBeFocused();
  await page.keyboard.press("Enter");
  await expect(page.getByText("Moves: 0", { exact: true })).toBeVisible();
  await expect(cards(page).nth(0)).toHaveAttribute("tabindex", "0");
});

